// Content with portions generated by generative AI platform
package org.eclipse.kura.web;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.eclipse.kura.identity.IdentityService;
import org.junit.After;

/**
 * Helper for the Web Console session lifecycle features. Provides minimal in memory fakes of the servlet request,
 * response and session that record whether a session has been allocated, and a {@link Console} instance wired with a
 * fake {@link IdentityService}.
 */
public abstract class WebConsoleSessionTestBase {

    protected static final String VALID_USERNAME = "admin";
    protected static final String VALID_PASSWORD = "correct-password";

    protected Console console;
    protected HttpServletRequest request;
    protected HttpServletResponse response;

    protected int sessionCreationCount;
    protected Map<String, Object> sessionAttributes;
    protected boolean sessionValid;
    protected boolean sessionIdChanged;
    protected Integer sentError;

    private HttpSession session;
    private String sessionId;

    @After
    public void cleanUp() {
        Console.setInstance(null);
        Console.setConsoleOptions(null);
    }

    protected void givenConsole() throws ReflectiveOperationException {
        givenConsoleWithOptions(null);
    }

    protected void givenConsoleWithOptions(final Map<String, Object> properties) throws ReflectiveOperationException {
        this.console = new Console();
        Console.setInstance(this.console);
        Console.setConsoleOptions(
                properties == null ? ConsoleOptions.defaultConfiguration() : ConsoleOptions.fromProperties(properties));

        final Field userManager = Console.class.getDeclaredField("userManager");
        userManager.setAccessible(true);
        userManager.set(this.console, new UserManager(newIdentityService()));
    }

    protected void givenRequestTo(final String uri) {
        this.sessionCreationCount = 0;
        this.sessionAttributes = null;
        this.sessionValid = false;
        this.sessionIdChanged = false;
        this.sentError = null;
        this.session = null;

        this.request = newRequest(uri);
        this.response = newResponse();
    }

    protected boolean isSessionAllocated() {
        return this.sessionCreationCount > 0;
    }

    private HttpServletRequest newRequest(final String uri) {
        return (HttpServletRequest) Proxy.newProxyInstance(
                HttpServletRequest.class.getClassLoader(),
                new Class<?>[] {HttpServletRequest.class},
                (proxy, method, args) -> {
                    switch (method.getName()) {
                        case "getRequestURI":
                            return uri;
                        case "getLocalPort":
                            return 443;
                        case "getRemoteAddr":
                            return "192.168.1.100";
                        case "getSession":
                            final boolean create = args == null || (Boolean) args[0];
                            return getSession(create);
                        case "changeSessionId":
                            this.sessionIdChanged = true;
                            this.sessionId = UUID.randomUUID().toString();
                            return this.sessionId;
                        default:
                            return defaultValue(method.getReturnType());
                    }
                });
    }

    private HttpSession getSession(final boolean create) {
        if (this.session != null && this.sessionValid) {
            return this.session;
        }

        if (!create) {
            return null;
        }

        this.sessionCreationCount++;
        this.sessionAttributes = new HashMap<>();
        this.sessionValid = true;
        this.sessionId = UUID.randomUUID().toString();
        this.session = newSession();

        return this.session;
    }

    private HttpSession newSession() {
        return (HttpSession) Proxy.newProxyInstance(
                HttpSession.class.getClassLoader(), new Class<?>[] {HttpSession.class}, (proxy, method, args) -> {
                    final String name = method.getName();

                    if (!this.sessionValid && !"getId".equals(name)) {
                        throw new IllegalStateException("session has been invalidated");
                    }

                    switch (name) {
                        case "getId":
                            return this.sessionId;
                        case "getAttribute":
                            return this.sessionAttributes.get(args[0]);
                        case "setAttribute":
                            this.sessionAttributes.put((String) args[0], args[1]);
                            return null;
                        case "removeAttribute":
                            this.sessionAttributes.remove(args[0]);
                            return null;
                        case "invalidate":
                            this.sessionValid = false;
                            return null;
                        default:
                            return defaultValue(method.getReturnType());
                    }
                });
    }

    private HttpServletResponse newResponse() {
        return (HttpServletResponse) Proxy.newProxyInstance(
                HttpServletResponse.class.getClassLoader(),
                new Class<?>[] {HttpServletResponse.class},
                (proxy, method, args) -> {
                    if ("sendError".equals(method.getName())) {
                        this.sentError = (Integer) args[0];
                    }
                    return defaultValue(method.getReturnType());
                });
    }

    private static IdentityService newIdentityService() {
        return (IdentityService) Proxy.newProxyInstance(
                IdentityService.class.getClassLoader(),
                new Class<?>[] {IdentityService.class},
                (proxy, method, args) -> {
                    switch (method.getName()) {
                        case "checkPassword":
                            if (!VALID_USERNAME.equals(args[0])
                                    || !VALID_PASSWORD.equals(new String((char[]) args[1]))) {
                                // same failure mode as the real IdentityServiceImpl.checkPassword()
                                throw new KuraException(
                                        KuraErrorCode.SECURITY_EXCEPTION,
                                        "Password authentication is not enabled or password does not match");
                            }
                            return null;
                        case "getIdentityConfiguration":
                            return Optional.empty();
                        default:
                            return defaultValue(method.getReturnType());
                    }
                });
    }

    private static Object defaultValue(final Class<?> type) {
        if (!type.isPrimitive() || type == void.class) {
            return null;
        } else if (type == boolean.class) {
            return false;
        } else if (type == long.class) {
            return 0L;
        } else {
            return 0;
        }
    }
}
